SELECT MIN(hcpcs_description) AS `TEMP(attr:hcpcs_description:nk)(2092202119)(0)`, MAX(hcpcs_description) AS `TEMP(attr:hcpcs_description:nk)(3741561916)(0)`, AVG((average_Medicare_allowed_amt - average_Medicare_payment_amt)) AS `avg:Calculation_9940518082838207:ok`, CAST(npi AS SIGNED) AS npi, nppes_provider_street1 AS nppes_provider_street1 FROM taxpayer WHERE ((hcpcs_description = 'Initial hospital care') AND (nppes_provider_state = 'WA')) GROUP BY npi, nppes_provider_street1, npi;
